// ============================================================
// HEIC/HEIF Conversion Check + EXIF Metadata Extraction
// ============================================================
// iPhone photos are often HEIC format which CompreFace can't read.
// This node:
//   1. Checks if the file is HEIC/HEIF
//   2. Extracts EXIF metadata (timestamp, GPS, camera model)
//   3. Generates an idempotency key to prevent duplicate processing
//
// The actual HEIC→JPEG conversion is done via a shell command in the
// next node since n8n's Code node doesn't have sharp/libheif built in.
// ============================================================

const items = $input.all();
const results = [];

for (const item of items) {
  const fileName = item.json.name || item.json.fileName || 'unknown';
  const mimeType = item.json.mimeType || '';
  const fileId = item.json.id || item.json.fileId || '';
  const fileSize = item.json.size || 0;

  // Determine if HEIC conversion is needed
  const isHeic = /\.(heic|heif)$/i.test(fileName) || 
                 mimeType.includes('heic') || 
                 mimeType.includes('heif');

  // Generate idempotency key from Google Drive file ID
  const idempotencyKey = `gdrive_${fileId}`;

  // Extract file extension
  const ext = fileName.split('.').pop().toLowerCase();
  const isVideo = ['mp4', 'mov', 'avi', 'mkv', 'webm'].includes(ext) ||
                  mimeType.startsWith('video/');

  // EXIF will be extracted after potential conversion
  // For now, use the Drive file's modifiedTime as fallback
  const driveTimestamp = item.json.modifiedTime || item.json.createdTime || new Date().toISOString();

  results.push({
    json: {
      ...item.json,
      _asp: {  // AutoSharePics metadata namespace
        originalFilename: fileName.replace(/'/g, "''"),
        gdriveFileId: fileId,
        mimeType: mimeType,
        fileSize: fileSize,
        isHeic: isHeic,
        isVideo: isVideo,
        needsConversion: isHeic,
        idempotencyKey: idempotencyKey,
        driveTimestamp: driveTimestamp,
        // Will be populated after EXIF extraction
        takenAt: null,
        cameraModel: null,
        gpsLat: null,
        gpsLng: null,
      }
    },
    binary: item.binary
  });
}

return results;

// ============================================================
// Video Metadata Extractor
// ============================================================
// For videos, we note them as video type.
// Keyframe extraction for face recognition will happen in Workflow 2
// using ffmpeg (which runs in n8n's Docker container).
// ============================================================

const items = $input.all();
const results = [];

for (const item of items) {
  const fileName = item.json.name || item.json.fileName || 'unknown';
  const fileId = item.json.id || item.json.fileId || '';
  const mimeType = item.json.mimeType || '';
  const driveTimestamp = item.json.modifiedTime || new Date().toISOString();

  results.push({
    json: {
      ...item.json,
      _asp: {
        originalFilename: fileName.replace(/'/g, "''"),
        gdriveFileId: fileId,
        mimeType: mimeType,
        fileSize: item.json.size || 0,
        isHeic: false,
        isVideo: true,
        needsConversion: false,
        idempotencyKey: `gdrive_${fileId}`,
        driveTimestamp: driveTimestamp,
        takenAt: null,
        cameraModel: null,
        gpsLat: null,
        gpsLng: null,
      }
    },
    binary: item.binary
  });
}

return results;
